DROP TABLE IF EXISTS `norma_bo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `norma_bo` (
  `id_norma_bo` int NOT NULL AUTO_INCREMENT,
  `id_tipo_norma` int NOT NULL,
  `id_emisor_norma` int NOT NULL,
  `numero` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `anio` int DEFAULT NULL,
  `fecha_publicacion` date DEFAULT NULL,
  `sintesis` text COLLATE utf8mb4_unicode_ci,
  `url_norma` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_estado_norma` int NOT NULL,
  `origen_carga` enum('Manual','Scraping') COLLATE utf8mb4_unicode_ci DEFAULT 'Scraping',
  `fecha_actualizacion` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_norma_bo`),
  KEY `id_tipo_norma` (`id_tipo_norma`),
  KEY `id_emisor_norma` (`id_emisor_norma`),
  KEY `id_estado_norma` (`id_estado_norma`),
  CONSTRAINT `norma_bo_ibfk_1` FOREIGN KEY (`id_tipo_norma`) REFERENCES `tipo_norma` (`id_tipo_norma`) ON DELETE RESTRICT,
  CONSTRAINT `norma_bo_ibfk_2` FOREIGN KEY (`id_emisor_norma`) REFERENCES `emisor_norma` (`id_emisor_norma`) ON DELETE RESTRICT,
  CONSTRAINT `norma_bo_ibfk_3` FOREIGN KEY (`id_estado_norma`) REFERENCES `estado_norma` (`id_estado_norma`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=431 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
